// The Worker entry: OpenNext's Next.js handler, a cron that keeps the Jikan
// cache warm (see lib/jikan.ts), and the live chat WebSocket, which is handled
// here (Next can't accept WebSocket upgrades) and routed to the ChatRoom
// Durable Object.

// @ts-expect-error generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";
import { ChatRoom } from "./chat-room";

export { ChatRoom };

async function sha256(s: string): Promise<string> {
  const d = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(s));
  return [...new Uint8Array(d)].map((b) => b.toString(16).padStart(2, "0")).join("");
}

// The member behind the session cookie, verified against D1 (same check as
// lib/auth), so the chat socket can't be opened or spoofed by a signed-out visitor.
async function chatUser(request: Request, env: CloudflareEnv) {
  const m = /(?:^|;\s*)cupcake_session=([^;]+)/.exec(request.headers.get("cookie") || "");
  if (!m) return null;
  try {
    const hash = await sha256(decodeURIComponent(m[1]));
    return await env.DB
      .prepare(
        `select u.id, u.handle, u.display_name, u.avatar_url, u.accent, u.is_plus
         from sessions s join users u on u.id = s.user_id
         where s.id = ? and s.expires_at > unixepoch()`,
      )
      .bind(hash)
      .first();
  } catch {
    return null;
  }
}

export default {
  async fetch(request: Request, env: CloudflareEnv, ctx: { waitUntil(p: Promise<unknown>): void }) {
    const url = new URL(request.url);
    if (url.pathname === "/api/chat/ws") {
      if (request.headers.get("Upgrade") !== "websocket") return new Response("expected websocket", { status: 426 });
      const user = await chatUser(request, env);
      if (!user) return new Response("sign in first", { status: 401 });
      const stub = env.CHAT.get(env.CHAT.idFromName("global"));
      const fwd = new URL(request.url);
      fwd.searchParams.set("u", JSON.stringify(user));
      return stub.fetch(new Request(fwd.toString(), request));
    }
    return handler.fetch(request, env, ctx);
  },
  async scheduled(_event: unknown, env: CloudflareEnv, ctx: { waitUntil(p: Promise<unknown>): void }) {
    ctx.waitUntil(handler.fetch(new Request("https://cupcake.internal/api/warm"), env, ctx));
  },
};
